class Calculator:
    def __init__(self):
        self.history = []

    def add(self, num1, num2):

        result = num1 + num2
        self.history.append(f"Added {num1} and {num2}, Result: {result}")
        return result

    def subtract(self, num1, num2):

        result = num1 - num2
        self.history.append(f"Subtracted {num2} from {num1}, Result: {result}")
        return result

    def multiply(self, num1, num2):

        result = num1 * num2
        self.history.append(f"Multiplied {num1} and {num2}, Result: {result}")
        return result

    def divide(self, num1, num2):

        if num2 == 0:
            raise ValueError("Cannot divide by zero")
        result = num1 / num2
        self.history.append(f"Divided {num1} by {num2}, Result: {result}")
        return result

    def get_history(self):

        return self.history


def main():
    calculator = Calculator()

    while True:
        print("Calculator Menu:")
        print("1. Addition")
        print("2. Subtraction")
        print("3. Multiplication")
        print("4. Division")
        print("5. Quit")

        choice = input("Choose an operation: ")

        if choice in ["1", "2", "3", "4"]:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))

            if choice == "1":
                result = calculator.add(num1, num2)
            elif choice == "2":
                result = calculator.subtract(num1, num2)
            elif choice == "3":
                result = calculator.multiply(num1, num2)
            elif choice == "4":
                try:
                    result = calculator.divide(num1, num2)
                except ValueError as e:
                    print(e)
                    continue

            print(f"Result: {result}")

        elif choice == "5":
            break

        else:
            print("Invalid choice. Please choose a valid operation.")

    print("Calculation History:")
    for i, result in enumerate(calculator.get_history()):
        print(f"{i+1}. {result}")


if __name__ == "__main__":
    main()
```



To use this calculator application, simply run the script and follow the prompts. Choose an operation by entering a number from 1 to 5. Enter the two numbers required for each operation, and the result will be displayed.

The calculation history is stored in the `history` list attribute of the `Calculator` class and can be accessed by calling the `get_history()` method.

Note that division by zero raises a `ValueError` exception, which is caught and handled by printing an error message.

