        operations = {
            "+": self.add,
            "-": self.subtract,
            "*": self.multiply,
            "/": self.divide
        }
        try:
            if operation in operations:
                return operations[operation](num1, num2)
            else:
                raise ValueError("Invalid operation!")
        except Exception as e:
            print(f"Error: {e}")
            return None

    def get_history(self):

        return self.history


